const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Articles</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>The German article does not always match the gender of the word in English. That is why it is best to learn nouns together with their article.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Article examples</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — table</div>\n      <div class=\"kurss-example\">die Tür — door</div>\n      <div class=\"kurss-example\">das Messer — knife</div>\n      <div class=\"kurss-example\">das Mädchen — girl</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Often DER</h4>\n    <p class=\"artikuli-explain\">DER is often used for male persons, days, months, seasons and some words with certain endings.</p>\n\n    <h5 class=\"artikuli-subtitle\">Rules</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → often DER, for example: der Computer, der Lehrer <span class=\"artikuli-note\">but not always</span></div>\n      <div class=\"kurss-example\">-ling → often DER, for example: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → often DER, for example: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">male persons → der Mann, der Vater</div>\n      <div class=\"kurss-example\">professions → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">car brands → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">days → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">months → der August, der Dezember</div>\n      <div class=\"kurss-example\">seasons → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Examples</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — man</div>\n      <div class=\"kurss-example\">der Vater — father</div>\n      <div class=\"kurss-example\">der Montag — Monday</div>\n      <div class=\"kurss-example\">der August — August</div>\n      <div class=\"kurss-example\">der Sommer — summer</div>\n      <div class=\"kurss-example\">der Lehrer — teacher</div>\n      <div class=\"kurss-example\">der Computer — computer</div>\n      <div class=\"kurss-example\">der Schmetterling — butterfly</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Often DIE</h4>\n    <p class=\"artikuli-explain\">DIE is often used for female persons, the plural and words ending in -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Rules</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">female persons → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">motorcycle brands → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">plural → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">plural almost always → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Examples</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — woman</div>\n      <div class=\"kurss-example\">die Mutter — mother</div>\n      <div class=\"kurss-example\">die Wohnung — apartment</div>\n      <div class=\"kurss-example\">die Rechnung — bill</div>\n      <div class=\"kurss-example\">die Freiheit — freedom</div>\n      <div class=\"kurss-example\">die Möglichkeit — possibility</div>\n      <div class=\"kurss-example\">die Mannschaft — team</div>\n      <div class=\"kurss-example\">die Nation — nation</div>\n      <div class=\"kurss-example\">die Universität — university</div>\n      <div class=\"kurss-example\">die Polizei — police</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Often DAS</h4>\n    <p class=\"artikuli-explain\">DAS is often used for diminutives ending in -chen / -lein, many words ending in -ment / -um, and verbs used as nouns.</p>\n\n    <h5 class=\"artikuli-subtitle\">Rules</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metals → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">chemical elements → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hotels → das Hotel</div>\n      <div class=\"kurss-example\">colours as nouns → das Rot, das Blau</div>\n      <div class=\"kurss-example\">verb as a noun → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">verbs as nouns → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Examples</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — child</div>\n      <div class=\"kurss-example\">das Mädchen — girl</div>\n      <div class=\"kurss-example\">das Häuschen — little house</div>\n      <div class=\"kurss-example\">das Instrument — instrument</div>\n      <div class=\"kurss-example\">das Zentrum — centre</div>\n      <div class=\"kurss-example\">das Museum — museum</div>\n      <div class=\"kurss-example\">das Essen — eating / food</div>\n      <div class=\"kurss-example\">das Lernen — learning</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Important exceptions / learn with the article</h4>\n    <p class=\"artikuli-explain\">For some words, the article cannot be reliably determined from the ending or from the gender of the word in English. It is best to learn them together with their article.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — door</div>\n      <div class=\"kurss-example\">das Messer — knife</div>\n      <div class=\"kurss-example\">die Sonne — sun</div>\n      <div class=\"kurss-example\">der Mond — moon</div>\n      <div class=\"kurss-example\">das Mädchen — girl</div>\n      <div class=\"kurss-example\">das Auto — car</div>\n      <div class=\"kurss-example\">der Käse — cheese</div>\n      <div class=\"kurss-example\">die Gabel — fork</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Endings and word groups help you guess the article, but they are not a 100% reliable rule. If you are not sure, learn the word together with its article.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Pronouns</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ and Dativ — pronoun forms.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — who?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — I</div><div class=\"kurss-example\">du — you (sg.)</div><div class=\"kurss-example\">er — he</div><div class=\"kurss-example\">sie — she</div><div class=\"kurss-example\">es — it</div><div class=\"kurss-example\">wir — we</div><div class=\"kurss-example\">ihr — you (pl.)</div><div class=\"kurss-example\">sie — they</div><div class=\"kurss-example\">Sie — you (formal)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — whom?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — me</div><div class=\"kurss-example\">dich — you (sg.)</div><div class=\"kurss-example\">ihn — him (m.)</div><div class=\"kurss-example\">sie — her (f.)</div><div class=\"kurss-example\">es — it</div><div class=\"kurss-example\">uns — us</div><div class=\"kurss-example\">euch — you (pl.)</div><div class=\"kurss-example\">sie — them</div><div class=\"kurss-example\">Sie — you (formal)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — to whom?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — (to) me</div><div class=\"kurss-example\">dir — (to) you (sg.)</div><div class=\"kurss-example\">ihm — (to) him / (to) it</div><div class=\"kurss-example\">ihr — (to) her</div><div class=\"kurss-example\">uns — (to) us</div><div class=\"kurss-example\">euch — (to) you (pl.)</div><div class=\"kurss-example\">ihnen — (to) them</div><div class=\"kurss-example\">Ihnen — (to) you (formal)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>How do you choose the form?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — subject of the sentence (who does it?)</li><li><span class=\"case-red\">Akkusativ</span> — direct object (whom?)</li><li><span class=\"case-green\">Dativ</span> — indirect object (to whom?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Examples</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — I see you.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — I see him.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — We like you.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — I help you.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — I give him a book.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — We thank you.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ is always the subject of the sentence, while Akkusativ and Dativ are objects. Look at the verb and ask: <span class=\"case-red\">whom?</span> or <span class=\"case-green\">to whom?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Vowels — long and short</h3>\n            <p class=\"kurss-lesson-intro\">In German, vowels can be long or short. This affects how a word is pronounced.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Long vowel</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — warm</div><div class=\"kurss-example\">gut (goot) — good</div><div class=\"kurss-example\">Tat (taht) — deed / action</div><div class=\"kurss-example\">Flur (floor) — hallway</div><div class=\"kurss-example\">Weg (vayk) — way / path</div><div class=\"kurss-example\">Hut (hoot) — hat</div><div class=\"kurss-example\">Hof (hohf) — yard / courtyard</div><div class=\"kurss-example\">Schlaf (shlahf) — sleep</div></div>\n              <p>If a vowel is followed by a single consonant, the vowel is often pronounced long.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Short vowel</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilts) — mushroom</div><div class=\"kurss-example\">Wort (vort) — word</div><div class=\"kurss-example\">Mund (munt) — mouth</div><div class=\"kurss-example\">bald (balt) — soon</div><div class=\"kurss-example\">scharf (sharf) — sharp</div><div class=\"kurss-example\">Feld (felt) — field</div><div class=\"kurss-example\">voll (fol) — full</div></div>\n              <p>If a vowel is followed by two or more consonants, the vowel is often pronounced short.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Endings en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (zing-en) — to sing</div><div class=\"kurss-example\">tragen (trah-gen) — to carry</div><div class=\"kurss-example\">Garten (gar-ten) — garden</div><div class=\"kurss-example\">Vogel (foh-gel) — bird</div><div class=\"kurss-example\">Segel (zay-gel) — sail</div><div class=\"kurss-example\">Braten (brah-ten) — roast</div><div class=\"kurss-example\">Bogen (boh-gen) — bow / arch</div><div class=\"kurss-example\">Spiegel (shpee-gel) — mirror</div><div class=\"kurss-example\">Finger (fing-er) — finger</div><div class=\"kurss-example\">Halter (hal-ter) — holder</div><div class=\"kurss-example\">Arbeiter (ar-by-ter) — worker</div><div class=\"kurss-example\">Häuser (hoy-zer) — houses</div><div class=\"kurss-example\">wieder (vee-der) — again</div><div class=\"kurss-example\">breiter (bry-ter) — wider</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>The letter h as a length mark</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rah-men) — frame</div><div class=\"kurss-example\">Ohr (ohr) — ear</div><div class=\"kurss-example\">Kohle (koh-luh) — coal</div><div class=\"kurss-example\">Zahl (tsahl) — number</div><div class=\"kurss-example\">ihn (een) — him</div><div class=\"kurss-example\">ihm (eem) — (to) him</div><div class=\"kurss-example\">Huhn (hoon) — chicken / hen</div><div class=\"kurss-example\">nahm (nahm) — took</div><div class=\"kurss-example\">nehmen (nay-men) — to take</div><div class=\"kurss-example\">Schuh (shoo) — shoe</div></div>\n              <p>In some words, h lengthens the preceding vowel. In such cases, h is usually not pronounced.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Endings with e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lam-puh) — lamp</div><div class=\"kurss-example\">Hase (hah-zuh) — hare</div><div class=\"kurss-example\">Knabe (knah-buh) — boy</div><div class=\"kurss-example\">Rabe (rah-buh) — raven</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Long i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dee) — the article “die”</div><div class=\"kurss-example\">diese (dee-zuh) — this / these</div><div class=\"kurss-example\">wieder (vee-der) — again</div><div class=\"kurss-example\">Fliege (flee-guh) — fly (insect)</div><div class=\"kurss-example\">Ziege (tsee-guh) — goat</div><div class=\"kurss-example\">Stiel (shteel) — stem / handle</div><div class=\"kurss-example\">Dieb (deep) — thief</div><div class=\"kurss-example\">hier (heer) — here</div></div>\n              <p>In German, the long i is often written as ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Double vowels</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (zahl) — hall</div><div class=\"kurss-example\">Saat (zaht) — seed / sowing</div><div class=\"kurss-example\">Staat (shtaht) — state</div><div class=\"kurss-example\">Beere (bay-ruh) — berry</div><div class=\"kurss-example\">See (zay) — lake / sea</div><div class=\"kurss-example\">Beet (bayt) — (garden) bed</div><div class=\"kurss-example\">Boot (boht) — boat</div><div class=\"kurss-example\">Moor (mohr) — moor / bog</div><div class=\"kurss-example\">Moos (mohs) — moss</div></div>\n              <p>Double vowels are usually pronounced long.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — wall</div><div class=\"kurss-example\">Wände (ven-duh) — walls</div><div class=\"kurss-example\">Vater (fah-ter) — father</div><div class=\"kurss-example\">Väter (feh-ter) — fathers</div><div class=\"kurss-example\">Schrank (shrank) — wardrobe / cupboard</div><div class=\"kurss-example\">Schränke (shren-kuh) — wardrobes / cupboards</div><div class=\"kurss-example\">Bank (bank) — bench / bank</div><div class=\"kurss-example\">Bänke (ben-kuh) — benches</div><div class=\"kurss-example\">Tal (tahl) — valley</div><div class=\"kurss-example\">Täler (teh-ler) — valleys</div></div>\n              <p>ä is the umlaut of a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (roh-zuh) — rose</div><div class=\"kurss-example\">Röschen (röhs-khen) — little rose</div><div class=\"kurss-example\">Ofen (oh-fen) — oven / stove</div><div class=\"kurss-example\">Öfen (öh-fen) — ovens / stoves</div><div class=\"kurss-example\">Rock (rok) — skirt</div><div class=\"kurss-example\">Röcke (rö-kuh) — skirts</div></div>\n              <p>ö is the umlaut of o.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (kurts) — short</div><div class=\"kurss-example\">kürzer (kür-tser) — shorter</div><div class=\"kurss-example\">Kunst (kunst) — art</div><div class=\"kurss-example\">Künste (kün-stuh) — arts</div><div class=\"kurss-example\">Mutter (mu-ter) — mother</div><div class=\"kurss-example\">Mütter (mü-ter) — mothers</div></div>\n              <p>ü is the umlaut of u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diphthongs: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (bowm) — tree</div><div class=\"kurss-example\">Bäume (boy-muh) — trees</div><div class=\"kurss-example\">Haus (hows) — house</div><div class=\"kurss-example\">Häuser (hoy-zer) — houses</div><div class=\"kurss-example\">Strauch (shtrowkh) — shrub / bush</div><div class=\"kurss-example\">Sträucher (shtroy-kher) — shrubs / bushes</div><div class=\"kurss-example\">Maus (mows) — mouse</div><div class=\"kurss-example\">Mäuse (moy-zuh) — mice</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diphthongs: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (hoy-tuh) — today</div><div class=\"kurss-example\">Leute (loy-tuh) — people</div><div class=\"kurss-example\">neu (noy) — new</div><div class=\"kurss-example\">neun (noyn) — nine</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diphthongs: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (myne) — my</div><div class=\"kurss-example\">dein (dyne) — your</div><div class=\"kurss-example\">sein (zyne) — his / its / to be</div><div class=\"kurss-example\">frei (fry) — free</div><div class=\"kurss-example\">arbeiten (ar-by-ten) — to work</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Pronunciation notes for Lesson 2</h4>\n              <ul class=\"kurss-summary-list\"><li>in the words ich, nicht, rechnen, zeichnen, “ch” is pronounced soft (like a breathy “h” in “huge”)</li><li>in the words arbeiten and zeichnen, “ei” is pronounced like “eye”</li><li>“sp” at the beginning of a word is pronounced like “shp”</li><li>in the verb tun, the letter “u” is pronounced long (like “oo” in “too”)</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Summary</h4>\n              <ul class=\"kurss-summary-list\"><li>one consonant after a vowel → often a long vowel</li><li>two or more consonants → often a short vowel</li><li>h can lengthen a vowel</li><li>ie often means a long i (like “ee”)</li><li>double vowels are usually long</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Consonants and letter combinations</h3>\n            <p class=\"kurss-lesson-intro\">In German, some consonants and letter combinations are pronounced differently from how they are written. This lesson covers the most important examples for beginners.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Consonants</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (das raht) — wheel</div><div class=\"kurss-example\">die Räder (dee reh-der) — wheels</div><div class=\"kurss-example\">Bad (baht) — bath</div><div class=\"kurss-example\">Bäder (beh-der) — baths</div></div>\n              <p>At the end of a word, consonants are often not pronounced the way they are written.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>“ch” can be pronounced soft or hard. In some words it sounds like a breathy “h” (as in “huge”), in others it is closer to a throaty “k” (as in Scottish “loch”).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rekh-nen) — to calculate</div><div class=\"kurss-example\">zeichnen (tsykh-nen) — to draw</div><div class=\"kurss-example\">nicht (nikht) — not</div><div class=\"kurss-example\">schlecht (shlekht) — bad</div><div class=\"kurss-example\">mich (mikh) — me</div><div class=\"kurss-example\">dich (dikh) — you (object)</div><div class=\"kurss-example\">Strauch (shtrowkh) — shrub / bush</div><div class=\"kurss-example\">noch (nokh) — still / yet</div><div class=\"kurss-example\">Nacht (nakht) — night</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>In German, “sch” is pronounced like English “sh”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (shoo-luh) — school</div><div class=\"kurss-example\">Schüler (shüh-ler) — pupil / student</div><div class=\"kurss-example\">Schiff (shif) — ship</div><div class=\"kurss-example\">Schraube (shrow-buh) — screw</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp and st at the beginning of a word</h4>\n              <p>At the beginning of a word or syllable, “sp” is often pronounced like “shp”, and “st” like “sht”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (shpee-len) — to play</div><div class=\"kurss-example\">Sprung (shprung) — jump / leap</div><div class=\"kurss-example\">stehen (shtay-en) — to stand</div><div class=\"kurss-example\">Stall (shtal) — stable / barn</div><div class=\"kurss-example\">Stand (shtant) — position / stand</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>In German, “qu” is usually pronounced like “kv”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvahl) — torment / agony</div><div class=\"kurss-example\">Quartier (kvar-teer) — quarters / accommodation</div><div class=\"kurss-example\">quer (kvayr) — across / crosswise</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s and z</h4>\n              <p>At the beginning of a word, “s” often sounds like English “z”. The letter “z” in German sounds like “ts” (as in “cats”).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (zah-gen) — to say</div><div class=\"kurss-example\">singen (zing-en) — to sing</div><div class=\"kurss-example\">Rose (roh-zuh) — rose</div><div class=\"kurss-example\">Zahl (tsahl) — number</div><div class=\"kurss-example\">Zeit (tsyte) — time</div><div class=\"kurss-example\">Zink (tsink) — zinc</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>In German, “v” is often pronounced like “f”. In loanwords it often sounds like English “v”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fah-ter) — father</div><div class=\"kurss-example\">von (fon) — from / of</div><div class=\"kurss-example\">viel (feel) — much / a lot</div><div class=\"kurss-example\">vier (feer) — four</div><div class=\"kurss-example\">Villa (vil-la) — villa</div><div class=\"kurss-example\">Klavier (kla-veer) — piano</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x and y</h4>\n              <p>“x” is pronounced like “ks”. In some words “y” is pronounced like “ü”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (fay-liks) — Felix</div><div class=\"kurss-example\">Axt (akst) — axe</div><div class=\"kurss-example\">Mystik (müs-tik) — mysticism</div><div class=\"kurss-example\">Mythe (mü-tuh) — myth</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>In German, “ß” is pronounced like “s” (as in “see”).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (foos) — foot</div><div class=\"kurss-example\">Füße (füh-suh) — feet</div><div class=\"kurss-example\">Grüße (grüh-suh) — greetings</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Summary</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → sh</li><li>sp / st at the start → shp / sht</li><li>qu → kv</li><li>z → ts</li><li>v often → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Verb basics</h3>\n            <p class=\"kurss-lesson-intro\">Lesson 1 verbs and their forms (conjugation).</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Verbs</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — to come</div><div class=\"kurss-example\">gehen — to go</div><div class=\"kurss-example\">stehen — to stand</div><div class=\"kurss-example\">singen — to sing</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — I come</div><div class=\"kurss-example\">du kommst — you come</div><div class=\"kurss-example\">er kommt — he comes</div><div class=\"kurss-example\">sie kommt — she comes</div><div class=\"kurss-example\">wir kommen — we come</div><div class=\"kurss-example\">ihr kommt — you (pl.) come</div><div class=\"kurss-example\">sie kommen — they come</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — I go</div><div class=\"kurss-example\">du gehst — you go</div><div class=\"kurss-example\">er geht — he goes</div><div class=\"kurss-example\">sie geht — she goes</div><div class=\"kurss-example\">wir gehen — we go</div><div class=\"kurss-example\">ihr geht — you (pl.) go</div><div class=\"kurss-example\">sie gehen — they go</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — I stand</div><div class=\"kurss-example\">du stehst — you stand</div><div class=\"kurss-example\">er steht — he stands</div><div class=\"kurss-example\">sie steht — she stands</div><div class=\"kurss-example\">wir stehen — we stand</div><div class=\"kurss-example\">ihr steht — you (pl.) stand</div><div class=\"kurss-example\">sie stehen — they stand</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — I sing</div><div class=\"kurss-example\">du singst — you sing</div><div class=\"kurss-example\">er singt — he sings</div><div class=\"kurss-example\">sie singt — she sings</div><div class=\"kurss-example\">wir singen — we sing</div><div class=\"kurss-example\">ihr singt — you (pl.) sing</div><div class=\"kurss-example\">sie singen — they sing</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Lesson 2 verbs</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — to play</div><div class=\"kurss-example\">arbeiten — to work</div><div class=\"kurss-example\">fragen — to ask</div><div class=\"kurss-example\">antworten — to answer</div><div class=\"kurss-example\">rechnen — to calculate</div><div class=\"kurss-example\">zeichnen — to draw</div><div class=\"kurss-example\">tun — to do</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — I play</div><div class=\"kurss-example\">du spielst — you play</div><div class=\"kurss-example\">er spielt — he plays</div><div class=\"kurss-example\">sie spielt — she plays</div><div class=\"kurss-example\">wir spielen — we play</div><div class=\"kurss-example\">ihr spielt — you (pl.) play</div><div class=\"kurss-example\">sie spielen — they play</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — I work</div><div class=\"kurss-example\">du arbeitest — you work</div><div class=\"kurss-example\">er arbeitet — he works</div><div class=\"kurss-example\">sie arbeitet — she works</div><div class=\"kurss-example\">wir arbeiten — we work</div><div class=\"kurss-example\">ihr arbeitet — you (pl.) work</div><div class=\"kurss-example\">sie arbeiten — they work</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — I ask</div><div class=\"kurss-example\">du fragst — you ask</div><div class=\"kurss-example\">er fragt — he asks</div><div class=\"kurss-example\">sie fragt — she asks</div><div class=\"kurss-example\">wir fragen — we ask</div><div class=\"kurss-example\">ihr fragt — you (pl.) ask</div><div class=\"kurss-example\">sie fragen — they ask</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — I answer</div><div class=\"kurss-example\">du antwortest — you answer</div><div class=\"kurss-example\">er antwortet — he answers</div><div class=\"kurss-example\">sie antwortet — she answers</div><div class=\"kurss-example\">wir antworten — we answer</div><div class=\"kurss-example\">ihr antwortet — you (pl.) answer</div><div class=\"kurss-example\">sie antworten — they answer</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — I calculate</div><div class=\"kurss-example\">du rechnest — you calculate</div><div class=\"kurss-example\">er rechnet — he calculates</div><div class=\"kurss-example\">sie rechnet — she calculates</div><div class=\"kurss-example\">wir rechnen — we calculate</div><div class=\"kurss-example\">ihr rechnet — you (pl.) calculate</div><div class=\"kurss-example\">sie rechnen — they calculate</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — I draw</div><div class=\"kurss-example\">du zeichnest — you draw</div><div class=\"kurss-example\">er zeichnet — he draws</div><div class=\"kurss-example\">sie zeichnet — she draws</div><div class=\"kurss-example\">wir zeichnen — we draw</div><div class=\"kurss-example\">ihr zeichnet — you (pl.) draw</div><div class=\"kurss-example\">sie zeichnen — they draw</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — I do</div><div class=\"kurss-example\">du tust — you do</div><div class=\"kurss-example\">er tut — he does</div><div class=\"kurss-example\">sie tut — she does</div><div class=\"kurss-example\">wir tun — we do</div><div class=\"kurss-example\">ihr tut — you (pl.) do</div><div class=\"kurss-example\">sie tun — they do</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Sentence structure</h3>\n            <p class=\"kurss-lesson-intro\">In a German question, the verb usually comes first.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Examples</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — You are coming.</div><div class=\"kurss-example\">Kommst du? — Are you coming?</div><div class=\"kurss-example\">Er singt. — He is singing.</div><div class=\"kurss-example\">Singt er? — Is he singing?</div><div class=\"kurss-example\">Stehst du? — Are you standing?</div><div class=\"kurss-example\">Ja, ich stehe. — Yes, I am standing.</div><div class=\"kurss-example\">Geht ihr? — Are you going?</div><div class=\"kurss-example\">Ja, wir gehen. — Yes, we are going.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Questions with “was”</h4>\n              <p>If a question begins with a question word, the verb in German usually comes immediately after the question word.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — What are you doing?</div><div class=\"kurss-example\">Was tut er? — What is he doing?</div><div class=\"kurss-example\">Was tut sie? — What is she doing?</div><div class=\"kurss-example\">Was tun sie? — What are they doing?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Negation with “nicht”</h4>\n              <p>If the negation “nicht” refers to the verb, in German it usually comes after the verb.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — I am not playing.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul is not asking.</div><div class=\"kurss-example\">Er kommt nicht. — He is not coming.</div><div class=\"kurss-example\">Sie singen nicht. — They are not singing.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Sentences from Lesson 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Are you playing?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — No, I am not playing, I am working.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul is not asking, he is working.</div><div class=\"kurss-example\">Arbeitest du? — Are you working?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — No, I am not working, I am singing.</div><div class=\"kurss-example\">Was tut Paul? — What is Paul doing?</div><div class=\"kurss-example\">Er spielt. — He is playing.</div><div class=\"kurss-example\">Was tut Marie? — What is Marie doing?</div><div class=\"kurss-example\">Sie singt. — She is singing.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul is playing, but Marie is singing.</div><div class=\"kurss-example\">Singt ihr? — Are you singing?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — No, we are not singing, we are working.</div><div class=\"kurss-example\">Was tun Paul und Marie? — What are Paul and Marie doing?</div><div class=\"kurss-example\">Sie fragen. — They are asking.</div><div class=\"kurss-example\">Sie antworten nicht. — They are not answering.</div><div class=\"kurss-example\">Wer arbeitet? — Who is working?</div><div class=\"kurss-example\">Wir arbeiten. — We are working.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — We are calculating and drawing.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — They come, ask, answer, work, play, sing and go.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Lesson 2</h3>\n            <p class=\"kurss-lesson-intro\">Lesson two: dialogues, words, pronunciation, grammar and translation.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogues / sentences</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Words</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — to play</div>\n                  <div class=\"kurss-example\">nein — no</div>\n                  <div class=\"kurss-example\">nicht — not</div>\n                  <div class=\"kurss-example\">arbeiten — to work</div>\n                  <div class=\"kurss-example\">fragen — to ask</div>\n                  <div class=\"kurss-example\">was tut er? — what is he doing?</div>\n                  <div class=\"kurss-example\">was tun sie? — what are they doing?</div>\n                  <div class=\"kurss-example\">aber — but</div>\n                  <div class=\"kurss-example\">antworten — to answer</div>\n                  <div class=\"kurss-example\">rechnen — to calculate, to do sums</div>\n                  <div class=\"kurss-example\">zeichnen — to draw</div>\n                  <div class=\"kurss-example\">Marie — Mary</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciation</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In the words ich, nicht, rechnen, zeichnen the sound ch is pronounced softly, roughly like the h at the start of huge or hue, but with more friction.</div><div class=\"kurss-example\">In the words arbeiten, zeichnen the diphthong ei is pronounced roughly like the i in fine or the word eye.</div><div class=\"kurss-example\">The consonant cluster sp is pronounced shp: spielen (shpeelen).</div><div class=\"kurss-example\">In the verb tun the u is pronounced long in all persons.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammar</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Endings with e</h4>\n                  <div class=\"lesson1-grammar-note\">If the verb stem ends in t, d or chn, an e is inserted before the endings -st and -t in conjugation.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>The question word</h4>\n                  <div class=\"lesson1-grammar-note\">In questions that begin with a question word, for example what? who? which? why? what for? etc., the verb comes immediately after the question word.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — What are you doing?</div><div class=\"kurss-example\">Was tut er? — What is he doing?</div><div class=\"kurss-example\">Was tut sie? — What is she doing?</div><div class=\"kurss-example\">Was tun sie? — What are they doing?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Negation with nicht</h4>\n                  <div class=\"lesson1-grammar-note\">If the negation nicht refers to the verb, the negating word comes after the verb.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — He is not coming.</div><div class=\"kurss-example\">Sie singen nicht. — They are not singing.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Translate</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lesson 2 translation card\">\n                    <span class=\"lesson1-training-progress\">Lesson 2 · Translate: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Who is asking?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Click the card to see the German translation. After the answer, the next click shows the next card.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Lesson 6</h3>\n    <p class=\"kurss-lesson-intro\">Numbers, the plural, umlauts and plural forms of nouns.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogues / sentences</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Words</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — is located, is, lies</div><div class=\"kurss-example\">der Bleistift (bly-shtift) — the pencil</div><div class=\"kurss-example\">einige (eye-nig-uh) — some, a few</div><div class=\"kurss-example\">hinlegen — to put down</div><div class=\"kurss-example\">legt hin — puts down</div><div class=\"kurss-example\">wieder (veeder) — again</div><div class=\"kurss-example\">aufmachen — to open</div><div class=\"kurss-example\">er macht auf — he opens</div><div class=\"kurss-example\">anspitzen (an-shpitsen) — to sharpen</div><div class=\"kurss-example\">er spitzt an — he sharpens</div><div class=\"kurss-example\">sich setzen — to sit down</div><div class=\"kurss-example\">setzt sich — sits down</div><div class=\"kurss-example\">der Schlüssel (shlüssel) — the key</div><div class=\"kurss-example\">das Fenster (fenster) — the window</div><div class=\"kurss-example\">die Tafel (dee tahfel) — the blackboard</div><div class=\"kurss-example\">der Garten — the garden</div><div class=\"kurss-example\">der Löffel — the spoon</div><div class=\"kurss-example\">zählen (tsaylen) — to count</div><div class=\"kurss-example\">die Nadel — the needle</div><div class=\"kurss-example\">was ist das — what is this?</div><div class=\"kurss-example\">der Hammer — the hammer</div><div class=\"kurss-example\">die Hämmer — the hammers</div><div class=\"kurss-example\">der Deckel (dair deckel) — the lid</div><div class=\"kurss-example\">der Teller — the plate</div><div class=\"kurss-example\">der Wagen — the cart</div><div class=\"kurss-example\">der Schlitten — the sledge</div><div class=\"kurss-example\">das Ding — the thing</div><div class=\"kurss-example\">die Dinge — the things</div><div class=\"kurss-example\">wie sind die Dinge? — what are the things like?</div><div class=\"kurss-example\">voll (fol) — full</div><div class=\"kurss-example\">leer (lair) — empty</div><div class=\"kurss-example\">schwer (shvair) — heavy, difficult</div><div class=\"kurss-example\">leicht — light</div><div class=\"kurss-example\">der Eimer — the bucket</div><div class=\"kurss-example\">wieviel (vee-feel) — how much, how many</div><div class=\"kurss-example\">wieviel Nadeln — how many needles</div><div class=\"kurss-example\">hier (heer) — here</div><div class=\"kurss-example\">dort — there</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciation</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä is the umlaut of the vowel a and is pronounced like a short or long closed e.</div><div class=\"kurss-example\">Examples: das Mädchen (mayt-khen), die Bänke (dee benk-uh), der Vater (dair fahter), die Väter (dee fayter).</div><div class=\"kurss-example\">ü is the umlaut of the vowel u. To pronounce it, round your lips strongly and try to say ee with your lips rounded.</div><div class=\"kurss-example\">Examples: fünf, der Schlüssel (shlüssel).</div><div class=\"kurss-example\">ö is pronounced with rounded lips while trying to say e: der Löffel.</div><div class=\"kurss-example\">A doubled vowel indicates a long vowel: leer (lair).</div><div class=\"kurss-example\">The diphthong eu is pronounced like oy in boy: neun (noyn).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammar</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Grammar and explanations</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In the present tense the stressed prefix of a compound verb separates from the verb and goes to the end of the sentence.</div><div class=\"kurss-example\">Examples: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">When used with a noun, the numeral one has a form for each of the three genders: masculine ein, feminine eine, neuter ein.</div><div class=\"kurss-example\">Examples: ein Schüler — one pupil; eine Schülerin — one schoolgirl; ein Kind — one child.</div><div class=\"kurss-example\">Numbers: eins, zwei, drei, vier (feer), fünf, sechs (zeks), sieben (zeeben), acht, neun (noyn), zehn (tsayn).</div><div class=\"kurss-example\">In German the linking verb has a singular and a plural form: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">In English the demonstrative this changes in number, but German uses a single form: das.</div><div class=\"kurss-example\">Examples: this is a hammer — das ist ein Hammer; this is a needle — das ist eine Nadel; these are hammers — das sind Hämmer; these are needles — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — cart and der Schlitten — sledge are used in German in both the singular and the plural.</div><div class=\"kurss-example\">Masculine and neuter nouns ending in -er, -el, -en often take no ending in the plural.</div><div class=\"kurss-example\">Examples: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Feminine nouns ending in -el, -er add -n in the plural.</div><div class=\"kurss-example\">Examples: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Exceptions: die Mutter (mother) — die Mütter (mothers); die Tochter (daughter) — die Töchter (daughters).</div><div class=\"kurss-example\">The indefinite article has no plural: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">In a statement the verb of the predicate comes in second position: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Translate</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lesson 6 translation card\"><span class=\"lesson1-training-progress\">Lesson 6 · Translate: 1 / 21</span><span class=\"lesson1-training-text\">Paul takes a pencil and draws.</span></button><p class=\"lesson1-training-hint\">Click the card to see the German translation. After the answer, the next click shows the next card.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Lesson 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, the accusative, sitzen, fragen and the ending -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogues / sentences</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Words</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zitsen) — to sit</div>\n        <div class=\"kurss-example\">fragen (frahgen) — to ask</div>\n        <div class=\"kurss-example\">der Lehrer (dair layrer) — the teacher</div>\n        <div class=\"kurss-example\">gut (goot) — well</div>\n        <div class=\"kurss-example\">wen (vayn) — whom</div>\n        <div class=\"kurss-example\">loben — to praise</div>\n        <div class=\"kurss-example\">der Schüler (shüler) — the pupil</div>\n        <div class=\"kurss-example\">klein — small, little</div>\n        <div class=\"kurss-example\">groß (grohs) — big, large</div>\n        <div class=\"kurss-example\">die Lehrerin — the female teacher</div>\n        <div class=\"kurss-example\">die Schülerin — the schoolgirl</div>\n        <div class=\"kurss-example\">schlecht (shlekht) — badly</div>\n        <div class=\"kurss-example\">tadeln — to scold</div>\n        <div class=\"kurss-example\">oder (ohder) — or</div>\n        <div class=\"kurss-example\">das Kind (kint) — the child</div>\n        <div class=\"kurss-example\">artig (ahrtikh) — well-behaved</div>\n        <div class=\"kurss-example\">die Mutter — the mother</div>\n        <div class=\"kurss-example\">lieben (leeben) — to love</div>\n        <div class=\"kurss-example\">der Vater (fahter) — the father</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciation</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz is a doubled z and is pronounced ts: sitzen (zitsen).</div>\n        <div class=\"kurss-example\">In German words v is pronounced like f: der Vater (fahter).</div>\n        <div class=\"kurss-example\">ß is called eszett and is pronounced like the English s in so: groß (grohs), weiß (vice).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammar</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominative and accusative</h4><div class=\"lesson1-grammar-note\">In English the subject answers the question who? or what?, and the direct object answers the question whom? or what?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In German the question in the nominative is wer? for people and was? for things.</div><div class=\"kurss-example\">In the accusative the question is wen? for people and was? for things.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">How the article changes in the accusative</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + accusative</h4><div class=\"lesson1-grammar-note\">In German the verb fragen takes the accusative.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">The ending -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Many feminine nouns are formed with the ending -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Position of the verb</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In a statement the verb comes in second position.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Translate</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lesson 5 translation card\"><span class=\"lesson1-training-progress\">Lesson 5 · Translate: 1 / 16</span><span class=\"lesson1-training-text\">Whom does the father love?</span></button><p class=\"lesson1-training-hint\">Click the card to see the German translation. After the answer, the next click shows the next card.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Lesson 4</h3>\n            <p class=\"kurss-lesson-intro\">The accusative, nehmen, hinlegen, hinausgehen and adjectives.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogues / sentences</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Words</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (naymen) — to take</div><div class=\"kurss-example\">er nimmt (nimt) — he takes</div><div class=\"kurss-example\">der Federhalter (dair fayder-halter) — the penholder</div><div class=\"kurss-example\">einen Federhalter — a penholder</div><div class=\"kurss-example\">zeigen — to show</div><div class=\"kurss-example\">schwarz (shvarts) — black</div><div class=\"kurss-example\">weiß (vice) — white</div><div class=\"kurss-example\">die Feder (dee fayder) — the nib</div><div class=\"kurss-example\">eine Feder — a nib</div><div class=\"kurss-example\">spitz (shpits) — pointed</div><div class=\"kurss-example\">hinlegen — to put down</div><div class=\"kurss-example\">legt hin — puts down</div><div class=\"kurss-example\">das Mädchen (mayt-khen) — the girl</div><div class=\"kurss-example\">das Messer — the knife</div><div class=\"kurss-example\">ein Messer — a knife</div><div class=\"kurss-example\">scharf — sharp</div><div class=\"kurss-example\">stumpf (shtoompf) — blunt</div><div class=\"kurss-example\">dann — then</div><div class=\"kurss-example\">hinaus — out, outside</div><div class=\"kurss-example\">hinausgehen — to go out</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciation</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">The endings -en, -er, -el are unstressed, so the e in these endings is barely audible: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">In German h can be either a sound or a sign that the preceding vowel is long.</div><div class=\"kurss-example\">When h marks a long vowel, it is not pronounced as a sound: nehmen (naymen).</div><div class=\"kurss-example\">If a vowel is followed by only one consonant, the vowel is pronounced long: die (dee) Feder (fayder), den (dayn).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammar</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>The accusative</h4><div class=\"lesson1-grammar-note\">In the feminine and neuter the accusative is the same as the nominative. Only the masculine changes.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Pronouns</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — masculine</div><div class=\"kurss-example\">sie — feminine</div><div class=\"kurss-example\">es — neuter</div><div class=\"kurss-example\">plural — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Separable verbs</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Adjectives</h4><div class=\"lesson1-grammar-note\">If an adjective is the predicate of a sentence, it changes neither for gender nor for number.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Negation with nicht</h4><div class=\"lesson1-grammar-note\">If nicht negates an adjective, it comes before the negated word.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nouns ending in -chen and -lein are neuter: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Translate</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lesson 4 translation card\"><span class=\"lesson1-training-progress\">Lesson 4 · Translate: 1 / 16</span><span class=\"lesson1-training-text\">The girl takes a penholder.</span></button><p class=\"lesson1-training-hint\">Click the card to see the German translation. After the answer, the next click shows the next card.</p></div></div></details>",
  "kurssLesson3": "            <h3>Lesson 3</h3>\n            <p class=\"kurss-lesson-intro\">Lesson three: dialogues, words, pronunciation, grammar and translation.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogues / sentences</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Words</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — who</div><div class=\"kurss-example\">was — what</div><div class=\"kurss-example\">hier — here</div><div class=\"kurss-example\">dort — there</div><div class=\"kurss-example\">der Tisch — the table</div><div class=\"kurss-example\">ein Tisch — a table</div><div class=\"kurss-example\">die Bank — the bench</div><div class=\"kurss-example\">eine Bank — a bench</div><div class=\"kurss-example\">liegen — to lie (be lying flat)</div><div class=\"kurss-example\">liegt hier ein Buch? — is there a book lying here?</div><div class=\"kurss-example\">das Buch — the book</div><div class=\"kurss-example\">ein Buch — a book</div><div class=\"kurss-example\">hängen — to hang</div><div class=\"kurss-example\">das Bild — the picture</div><div class=\"kurss-example\">ein Bild — a picture</div><div class=\"kurss-example\">die Tafel — the blackboard</div><div class=\"kurss-example\">eine Tafel — a blackboard</div><div class=\"kurss-example\">wie — how, what … like</div><div class=\"kurss-example\">ist — is</div><div class=\"kurss-example\">dick — thick, fat</div><div class=\"kurss-example\">das Heft — the exercise book</div><div class=\"kurss-example\">ein Heft — an exercise book</div><div class=\"kurss-example\">dünn — thin</div><div class=\"kurss-example\">niedrig — low</div><div class=\"kurss-example\">hoch — high, tall</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciation</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In German the long ee sound is written ie: liegen (leegen), hier (heer), wie (vee).</div><div class=\"kurss-example\">ck is a double k: dick (dik).</div><div class=\"kurss-example\">In adjectives and adverbs the ending -ig sounds like a soft -ich: niedrig (needrikh).</div><div class=\"kurss-example\">If the ending -ig is extended with e to -ige, the g is pronounced as a hard g: niedrige (needrig-uh) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammar</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>The subject</h4><div class=\"lesson1-grammar-note\">In German the subject answers the question wer? / was? and is in the nominative.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer? is used to ask about people.</div><div class=\"kurss-example\">was? is used to ask about things.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Articles</h4><div class=\"lesson1-grammar-note\">In German nouns have 3 genders: masculine, feminine and neuter. A noun is usually preceded by a little word called the article. It roughly corresponds to the English the or a.</div><h5 class=\"lesson2-subtitle\">The definite article</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">masculine — der</div><div class=\"kurss-example\">feminine — die</div><div class=\"kurss-example\">neuter — das</div><div class=\"kurss-example\">In the plural the definite article is die for all three genders.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">The indefinite article</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">masculine — ein</div><div class=\"kurss-example\">feminine — eine</div><div class=\"kurss-example\">neuter — ein</div><div class=\"kurss-example\">The indefinite article has no plural.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Proper nouns</h4><div class=\"lesson1-grammar-note\">No article is used before proper nouns.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Position of the verb</h4><div class=\"lesson1-grammar-note\">In a statement the verb comes in second position.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In German, objects that are upright are said to stand:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Objects in a horizontal position are said to lie:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Objects can also hang:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Translate</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lesson 3 translation card\"><span class=\"lesson1-training-progress\">Lesson 3 · Translate: 1 / 22</span><span class=\"lesson1-training-text\">Are you doing sums?</span></button><p class=\"lesson1-training-hint\">Click the card to see the German translation. After the answer, the next click shows the next card.</p></div></div></details>",
  "kurssLesson7": "            <h3>Lesson 7</h3>\n            <p class=\"kurss-lesson-intro\">Lesson seven: the imperative, the polite form of address and the plural.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogues / sentences</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Words</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — to sing</div><div class=\"kurss-example\">singe — sing (to one person)</div><div class=\"kurss-example\">singt — sing (to several people)</div><div class=\"kurss-example\">singen Sie — sing (polite form)</div><div class=\"kurss-example\">das Lied (dass leet) — the song</div><div class=\"kurss-example\">Sie — you (polite form)</div><div class=\"kurss-example\">zählen — to count</div><div class=\"kurss-example\">das Fräulein (froy-line) — young lady, Miss</div><div class=\"kurss-example\">der Müller — the miller</div><div class=\"kurss-example\">öffnen — to open</div><div class=\"kurss-example\">das Fenster (fenster) — the window</div><div class=\"kurss-example\">alle — all, everyone</div><div class=\"kurss-example\">der Spiegel (shpeegel) — the mirror</div><div class=\"kurss-example\">der Lappen — the rag, the cloth</div><div class=\"kurss-example\">der Spaten — the spade</div><div class=\"kurss-example\">der Besen — the broom</div><div class=\"kurss-example\">die Schaufel — the shovel</div><div class=\"kurss-example\">die Schüssel — the bowl</div><div class=\"kurss-example\">das Zimmer — the room</div><div class=\"kurss-example\">das Ufer (oofer) — the shore, the bank</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciation</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp at the beginning of a word or syllable is pronounced shp: der Spiegel (dair shpeegel).</div><div class=\"kurss-example\">sch is pronounced like the English sh: die Schaufel (dee showfel), die Schüssel (dee shüssel).</div><div class=\"kurss-example\">The diphthong äu is pronounced like the English oy: das Fräulein (dass froy-line).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammar</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>The imperative</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">The imperative in the 2nd person singular corresponds to the 2nd person singular of the verb without the personal ending -st, with the ending -e added.</div><div class=\"kurss-example\">Examples: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">The ending -e is very often dropped if the imperative is a single syllable without it: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>The plural imperative</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">The imperative in the 2nd person plural is the same as the 2nd person plural of the present tense, but it is used without the pronoun.</div><div class=\"kurss-example\">Examples: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>The polite form of address with Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">The polite form of address is the same as the 3rd person plural. The pronoun Sie is written with a capital letter and comes after the verb.</div><div class=\"kurss-example\">Examples: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">To make pronunciation easier, the verb öffnen inserts an e between the stem and the ending in the 2nd and 3rd person singular and the 2nd person plural: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Exercise</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lesson 7 exercise card\"><span class=\"lesson1-training-progress\">Lesson 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — to ask</span></button><p class=\"lesson1-training-hint\">Tap the card to see the imperative forms.</p></div></div></details>",
  "kurssLesson1": "            <h3>Lesson 1</h3>\n            <p class=\"kurss-lesson-intro\">Lesson one: verbs in the present tense, words, pronunciation, grammar and translation practice.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verbs in the present tense</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Verbs and their conjugation in the present tense.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — to come</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>I come</span><span>du</span><strong>kommst</strong><span>you come</span><span>er / sie</span><strong>kommt</strong><span>he / she comes</span><span>wir</span><strong>kommen</strong><span>we come</span><span>ihr</span><strong>kommt</strong><span>you (pl.) come</span><span>sie / Sie</span><strong>kommen</strong><span>they / you (polite) come</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — to go</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>I go</span><span>du</span><strong>gehst</strong><span>you go</span><span>er / sie</span><strong>geht</strong><span>he / she goes</span><span>wir</span><strong>gehen</strong><span>we go</span><span>ihr</span><strong>geht</strong><span>you (pl.) go</span><span>sie / Sie</span><strong>gehen</strong><span>they / you (polite) go</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — to stand</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>I stand</span><span>du</span><strong>stehst</strong><span>you stand</span><span>er / sie</span><strong>steht</strong><span>he / she stands</span><span>wir</span><strong>stehen</strong><span>we stand</span><span>ihr</span><strong>steht</strong><span>you (pl.) stand</span><span>sie / Sie</span><strong>stehen</strong><span>they / you (polite) stand</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — to sing</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>I sing</span><span>du</span><strong>singst</strong><span>you sing</span><span>er / sie</span><strong>singt</strong><span>he / she sings</span><span>wir</span><strong>singen</strong><span>we sing</span><span>ihr</span><strong>singt</strong><span>you (pl.) sing</span><span>sie / Sie</span><strong>singen</strong><span>they / you (polite) sing</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Examples</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Words</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>The approximate pronunciation of the words is given in brackets using English spelling.<br>Keep this in mind in the following lessons too.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (veer) — we</div><div class=\"kurss-example\">In the word “wir” the letter i is pronounced long.</div><div class=\"kurss-example\">kommen (kommen) — to come</div><div class=\"kurss-example\">gehen (gay-en) — to go</div><div class=\"kurss-example\">stehen (shtay-en) — to stand</div><div class=\"kurss-example\">singen (zing-en) — to sing</div><div class=\"kurss-example\">du (doo) kommst — you come</div><div class=\"kurss-example\">er (air) kommt — he comes</div><div class=\"kurss-example\">sie (zee) kommt — she comes</div><div class=\"kurss-example\">wer (vair) — who?</div><div class=\"kurss-example\">ja (yah) — yes</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciation</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">The correct pronunciation of the words, written with English spelling, is given in the lessons.</div><div class=\"kurss-example\">Wir (veer) — we. In the word wir the i is always pronounced long.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammar</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>The infinitive</h4><div class=\"lesson1-grammar-note\">The basic form of the verb. The infinitive usually ends in -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Present-tense endings</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Remove <span class=\"lesson1-ending-accent\">-en</span> from the infinitive and add the ending.</strong></p><p>Example: kommen → komm + ending</p><div class=\"lesson1-ending-process\" aria-label=\"How the present-tense endings are formed\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>infinitive</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>remove <span class=\"lesson1-ending-accent\">-en</span></strong><span>the stem remains</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>stem</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>add the ending</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Examples</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Questions</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>In a German question the verb usually moves to first position.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In English:<br>You come.<br>Do you come?</div><div class=\"kurss-example\">In German:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — you come<br>kommst du? — do you come?</div><div class=\"kurss-example\">er singt — he sings<br>singt er? — does he sing?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Distinguishing the persons</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — he comes</div><div class=\"kurss-example\">sie kommt — she comes</div><div class=\"kurss-example\">sie kommen — they come</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Translate</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lesson 1 practice card\">\n                    <span class=\"lesson1-training-progress\">Lesson 1 · Translate: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Are you coming?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Click the card to see the German translation. After the answer, the next click shows the next card.</p>\n                </div>\n              </div>\n            </details>"
};

